class _PinnedScan:
    """Iterator that holds a watermark lease until exhausted, closed, or collected."""

    def __init__(self, it: Iterator[tuple[str, bytes]], release) -> None:
        self._it = it
        self._release = release
        self._done = False

    def __iter__(self):
        return self

    def __next__(self):
        if self._done:
            raise StopIteration
        try:
            return next(self._it)
        except BaseException:
            self.close()
            raise

    def close(self) -> None:
        if not self._done:
            self._done = True
            self._it.close()
            self._release()

